export const blank=()=>({income:0,remaining:0,accounts:[],cards:[],investments:[],transactions:[],importNotes:[]});
export const total=(a,f)=>a.reduce((s,x)=>s+f(x),0);
export const isIn=t=>['income','yield','transfer_in'].includes(t.type);
export const typeLabels={income:'Receita',expense:'Despesa',transfer_in:'Transferência recebida',transfer_out:'Transferência enviada',yield:'Rendimento em conta',settlement:'Pagamento de fatura',card_payment:'Pagamento recebido pelo cartão'};
export const cardSpending=(d,id)=>total(d.transactions.filter(t=>t.cardId===id&&t.method==='Crédito'&&t.type!=='card_payment'),t=>t.amount);
export function calculate(d){const expenses=total(d.transactions.filter(x=>x.type==='expense'),x=>x.amount);const received=total(d.transactions.filter(x=>x.type==='income'),x=>x.amount);const openingBills=total(d.cards,x=>x.opening);const cardTotals=Object.fromEntries(d.cards.map(c=>{const spent=cardSpending(d,c.id);return[c.id,c.invoiceTotal>0?Math.max(0,c.invoiceTotal+spent-(c.invoiceBase??spent)):c.opening+spent]}));const balances=Object.fromEntries(d.accounts.map(a=>[a.id,a.balance+total(d.transactions.filter(t=>t.accountId===a.id&&t.method!=='Crédito'),t=>isIn(t)?t.amount:-t.amount)]));const accounts=total(Object.values(balances),x=>x);const cashYields=total(d.transactions.filter(t=>t.type==='yield'),t=>t.amount);const yields=total(d.investments,x=>x.yield)+cashYields;const invested=total(d.investments,x=>x.principal+x.yield);return{expenses:expenses+openingBills,received,cards:total(Object.values(cardTotals),x=>x),cardTotals,balances,accounts,yields,invested,net:accounts+invested-total(Object.values(cardTotals),x=>x),savings:Math.max(d.income,received)+cashYields-expenses-openingBills-d.remaining};}
export function validDate(x){return typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x))&&new Date(x+'T12:00:00Z').toISOString().slice(0,10)===x;}
export function validate(d,month){const money=n=>Number.isSafeInteger(n)&&Math.abs(n)<=99999999999;const nonneg=n=>money(n)&&n>=0;const str=s=>typeof s==='string'&&s.trim().length>0&&s.length<=120;const optional=s=>s===undefined||(typeof s==='string'&&s.length<=180);const list=a=>Array.isArray(a)&&a.length<=2000;const id=s=>typeof s==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(s);if(!d||!nonneg(d.income)||!nonneg(d.remaining)||!['accounts','cards','investments','transactions'].every(k=>list(d[k])))return false;if(d.importNotes&&(!Array.isArray(d.importNotes)||d.importNotes.length>100||!d.importNotes.every(s=>typeof s==='string'&&s.length<=1500)))return false;for(const key of ['accounts','cards','investments','transactions'])if(new Set(d[key].map(x=>x.id)).size!==d[key].length||!d[key].every(x=>id(x.id)))return false;if(!d.accounts.every(a=>str(a.name)&&money(a.balance)&&optional(a.details)))return false;if(!d.cards.every(c=>str(c.name)&&nonneg(c.opening)&&(!c.dueDate||validDate(c.dueDate))&&(c.invoiceTotal===undefined||nonneg(c.invoiceTotal))&&(c.invoiceCarry===undefined||nonneg(c.invoiceCarry))&&(c.invoiceBase===undefined||nonneg(c.invoiceBase))&&(!c.invoiceCarry||c.invoiceCarry<=(c.invoiceTotal||0))&&(!c.invoiceMonth||/^20\d{2}-(0[1-9]|1[0-2])$/.test(c.invoiceMonth))))return false;if(!d.investments.every(i=>str(i.name)&&nonneg(i.principal)&&money(i.yield)&&i.principal+i.yield>=0&&(!i.asOfDate||validDate(i.asOfDate)&&i.asOfDate.slice(0,7)===month)))return false;return d.transactions.every(t=>Object.hasOwn(typeLabels,t.type)&&str(t.description)&&str(t.category)&&nonneg(t.amount)&&t.amount>0&&validDate(t.date)&&t.date.slice(0,7)===month&&(!t.creditKind||['pix-credit','card'].includes(t.creditKind))&&['Pix','Débito','Dinheiro','Crédito','Não informado'].includes(t.method)&&(t.method==='Crédito'?['expense','transfer_out','card_payment'].includes(t.type)&&d.cards.some(c=>c.id===t.cardId)&&!t.accountId:t.type!=='card_payment'&&d.accounts.some(a=>a.id===t.accountId)&&!t.cardId));}

